<script setup>
import { computed, ref } from 'vue'
import { DEFAULT_THEME_ID, INITIAL_VISUAL_THEMES, loadVisualThemes, persistVisualThemes, parseVisualThemeJson, removeVisualTheme, validateVisualTheme } from '@/services/visualThemes'
import { useVisualThemes } from '@/composables/useVisualThemes'
import VisualThemePreview from './VisualThemePreview.vue'
import SeasonalThemeDecor from './SeasonalThemeDecor.vue'
const props=defineProps({userRole:String,posts:{type:Array,default:()=>[]},usageComplete:Boolean,embedded:Boolean})
const {themes,enabled,refresh}=useVisualThemes()
const selected=ref(DEFAULT_THEME_ID),draft=ref(''),notice=ref(loadVisualThemes().error),error=ref('')
const isNew=ref(false)
const editorMode=ref('visual'),activeGroup=ref('general'),previewMode=ref('social')
const form=computed(()=>{try{const value=JSON.parse(draft.value);return value?.config?.general&&value?.config?.social&&value?.config?.web?value:null}catch{return null}})
const fieldLabels={primary:'Color principal',secondary:'Color secundario',accent:'Acento',background:'Fondo',surface:'Paneles',text:'Texto',muted:'Texto secundario',highlight:'Destacados',title:'Título',description:'Descripción',labelBackground:'Fondo de etiqueta',labelEnd:'Final de etiqueta',labelText:'Texto de etiqueta',numberBackground:'Fondo de números',numberEnd:'Final de números',numberText:'Texto de números',cardBackground:'Fondo de tarjetas',cardEnd:'Final de tarjetas',cardBorder:'Borde de tarjetas',progressActive:'Progreso activo',progressMiddle:'Centro del progreso',progressEnd:'Final del progreso',progressInactive:'Progreso pendiente',arrowBackground:'Fondo de flecha',arrowEnd:'Final de flecha',arrowIcon:'Icono de flecha',arrowBorder:'Borde de flecha',gradientStart:'Inicio del fondo',gradientEnd:'Final del fondo',gradientOpacity:'Intensidad del fondo',glowOpacity:'Intensidad del brillo',effect:'Efecto',buttonBackground:'Fondo del botón',buttonText:'Texto del botón',border:'Bordes'}
function changeField(key,value){try{const next=JSON.parse(draft.value);if(key==='name')next.name=value;else next.config.decoration=value;draft.value=JSON.stringify(next,null,2)}catch{error.value='Corrige primero el JSON.'}}
function pickerColor(value){return /^#[a-f\d]{6}([a-f\d]{2})?$/i.test(value)?value.slice(0,7):'#000000'}
function changePicker(group,key,value){const current=form.value?.config[group]?.[key];changeColor(group,key,value+(current?.length===9?current.slice(7):''))}
const parsed=computed(()=>{try{return parseVisualThemeJson(draft.value)}catch{return null}})
const validationError=computed(()=>{try{parseVisualThemeJson(draft.value);return ''}catch(e){return e.message}})
const locked=computed(()=>props.userRole!=='admin')
const usage=computed(()=>props.posts.filter(p=>p.visualThemeId===selected.value).length)
function choose(id){selected.value=id;isNew.value=false;draft.value=JSON.stringify(themes.value.find(t=>t.id===id),null,2);error.value='';notice.value=''}
choose(selected.value)
function attempt(action){error.value='';notice.value='';try{if(locked.value)throw Error('Solo administradores.');action()}catch(e){error.value=e.message}}
function commit(items,message){persistVisualThemes(items,props.userRole);refresh();notice.value=message}
function create(duplicate=false){attempt(()=>{const source=duplicate?parseVisualThemeJson(draft.value):INITIAL_VISUAL_THEMES[0];const theme={...structuredClone(source),id:'tema-'+crypto.randomUUID(),name:duplicate?source.name+' (copia)':'Nuevo tema',version:1,archived:false};selected.value=theme.id;isNew.value=true;draft.value=JSON.stringify(theme,null,2);notice.value='Borrador local. Personaliza el tema y guarda para añadirlo.'})}
function save(){attempt(()=>{const value=parseVisualThemeJson(draft.value);if(!isNew.value&&value.id!==selected.value)throw Error('El identificador de un tema guardado es estable. Duplica para crear otro.');if(isNew.value&&themes.value.some(t=>t.id===value.id))throw Error('Ese identificador ya existe.');const prior=themes.value.find(t=>t.id===selected.value);if(prior&&!isNew.value)value.version=Math.max(prior.version+1,value.version);commit([...themes.value.filter(t=>t.id!==value.id),value],'Tema guardado solo en este navegador.');choose(value.id);notice.value='Tema guardado solo en este navegador.'})}
function archive(){attempt(()=>{if(selected.value===DEFAULT_THEME_ID)throw Error('El tema predeterminado no se puede archivar.');const theme=themes.value.find(t=>t.id===selected.value);commit(themes.value.map(t=>t.id===theme.id?{...t,archived:!t.archived,version:t.version+1}:t),'Estado actualizado. Los posts conservan su referencia y usan el diseño predeterminado si se archiva.');draft.value=JSON.stringify(themes.value.find(t=>t.id===selected.value),null,2)})}
function remove(){attempt(()=>{const next=removeVisualTheme(themes.value,selected.value,{role:props.userRole,posts:props.posts,usageComplete:props.usageComplete});commit(next,'Tema eliminado.');choose(DEFAULT_THEME_ID);notice.value='Tema eliminado de la biblioteca local.'})}
function restore(){attempt(()=>{const preset=INITIAL_VISUAL_THEMES.find(t=>t.id===selected.value);const current=themes.value.find(t=>t.id===selected.value)||parseVisualThemeJson(draft.value);draft.value=JSON.stringify({...structuredClone(preset||INITIAL_VISUAL_THEMES[0]),id:current.id,name:current.name,version:current.version},null,2);notice.value='Valores iniciales cargados en el borrador. Pulsa Guardar para confirmar.'})}
async function importFile(event){const file=event.target.files?.[0];if(!file)return;try{if(file.size>50000)throw Error('Archivo demasiado grande.');const theme=parseVisualThemeJson(await file.text());draft.value=JSON.stringify(theme,null,2);selected.value=theme.id;isNew.value=!themes.value.some(t=>t.id===theme.id);notice.value='Importación validada. Revisa la muestra y guarda para aplicarla.';error.value=''}catch(e){error.value=e.message}finally{event.target.value=''}}
function exportFile(){attempt(()=>{const value=parseVisualThemeJson(draft.value);const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=value.id+'-v'+value.version+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
function integration(key,value){attempt(()=>{localStorage.setItem('galaxia-visual-theme-integrations',JSON.stringify({...enabled.value,[key]:value}));window.dispatchEvent(new Event('galaxia-themes-changed'));refresh();notice.value='Integración actualizada solo en este navegador.'})}
function changeColor(group,key,value){try{const next=JSON.parse(draft.value);next.config[group][key]=value;draft.value=JSON.stringify(next,null,2)}catch{error.value='Corrige primero el JSON.'}}
const labels={general:'Colores generales',social:'Carrusel social',web:'Artículo web'}
defineExpose({createTheme:()=>create()})
</script>
<template>
 <section class="visual-theme-manager">
  <header v-if="!embedded"><div><h2>Temas visuales</h2><p>Colores y detalles para tus artículos e imágenes sociales.</p></div><button type="button" :disabled="locked" @click="create()">+ Crear tema</button></header>
  <div v-if="locked" role="alert">Solo los administradores pueden gestionar temas.</div>
  <template v-else>
   <div class="theme-integrations"><label><input type="checkbox" :checked="enabled.web" @change="integration('web',$event.target.checked)"> Artículos web</label><label><input type="checkbox" :checked="enabled.social" @change="integration('social',$event.target.checked)"> Generador social</label><small>Biblioteca local · los posts guardados conservan su tema.</small></div>
   <p v-if="error" role="alert" class="theme-error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
   <nav class="theme-gallery" aria-label="Temas disponibles">
    <button v-for="theme in themes" :key="theme.id" type="button" :aria-pressed="selected===theme.id" :class="{selected:selected===theme.id}" @click="choose(theme.id)">
     <div class="theme-cover" :style="{background:'linear-gradient(135deg,'+theme.config.general.background+','+theme.config.general.secondary+')'}"><SeasonalThemeDecor :season="theme.config.decoration" /><span class="sample-line" :style="{background:theme.config.general.primary}"></span><span class="sample-line short" :style="{background:theme.config.general.highlight}"></span><span class="theme-swatches"><i v-for="(color,i) in [theme.config.general.primary,theme.config.general.secondary,theme.config.general.highlight]" :key="i" :style="{background:color}"></i></span></div>
     <strong>{{theme.name}}</strong><small>{{theme.config.decoration==='halloween'||theme.config.decoration==='christmas'?'De temporada · ':''}}v{{theme.version}}{{theme.archived?' · Archivado':''}}</small>
    </button>
   </nav>
   <div class="theme-manager-layout">
    <div class="theme-draft">
     <div class="editor-heading"><div><h3>{{isNew?'Nuevo tema':form?.name||'Editar tema'}}</h3><small v-if="!isNew">{{usage}} publicaciones en la lista cargada</small></div><div class="segmented" aria-label="Modo de edición"><button :aria-pressed="editorMode==='visual'" @click="editorMode='visual'">Visual</button><button :aria-pressed="editorMode==='json'" @click="editorMode='json'">JSON avanzado</button></div></div>
     <template v-if="editorMode==='visual' && form">
      <div class="theme-basics"><label>Nombre del tema<input :value="form.name" maxlength="80" @input="changeField('name',$event.target.value)"></label><label>Decoración<select :value="form.config.decoration||'none'" @change="changeField('decoration',$event.target.value)"><option value="none">Sin decoración</option><option value="halloween">Halloween · luna y criaturas</option><option value="christmas">Navidad · nieve y adornos</option></select></label></div>
      <p class="theme-hint">Los detalles son estáticos y se incluyen en el artículo y en las imágenes exportadas. Puedes combinarlos con cualquier paleta.</p>
      <div class="group-tabs" aria-label="Sección de colores"><button v-for="(label,group) in labels" :key="group" :aria-pressed="activeGroup===group" @click="activeGroup=group">{{label}}</button></div>
      <div class="theme-colors"><label v-for="(value,key) in form.config[activeGroup]" :key="activeGroup+key"><span>{{fieldLabels[key]||key}}</span><div v-if="typeof value==='string' && key!=='effect'" class="color-control"><input type="color" :aria-label="fieldLabels[key]||key" :value="pickerColor(value)" @input="changePicker(activeGroup,key,$event.target.value)"><input :aria-label="'Hexadecimal '+(fieldLabels[key]||key)" :value="value" spellcheck="false" @input="changeColor(activeGroup,key,$event.target.value)"></div><div v-else-if="typeof value==='number'" class="range-control"><input type="range" min="0" max="1" step="0.01" :value="value" @input="changeColor(activeGroup,key,Number($event.target.value))"><output>{{Math.round(value*100)}}%</output></div><select v-else :value="value" @change="changeColor(activeGroup,key,$event.target.value)"><option value="none">Ninguno</option><option value="soft-glow">Brillo suave</option></select></label></div>
     </template>
     <label v-else class="json-editor">Configuración JSON<textarea v-model="draft" spellcheck="false" aria-label="Configuración JSON del tema"></textarea></label>
     <p v-if="!parsed" role="alert" class="theme-error">{{validationError}}</p>
     <div class="theme-actions"><button class="save-theme" type="button" @click="save" :disabled="!parsed">Guardar tema</button><button type="button" @click="create(true)" :disabled="!parsed">Duplicar</button></div>
     <details class="advanced-actions"><summary>Importar, exportar y administrar</summary><div class="theme-actions"><label class="theme-file">Importar JSON<input type="file" accept=".json,application/json" @change="importFile"></label><button type="button" :disabled="!parsed" @click="exportFile">Exportar JSON</button><button type="button" @click="restore">Restaurar valores</button><button v-if="!isNew&&selected!==DEFAULT_THEME_ID" type="button" @click="archive">Archivar / reactivar</button><button v-if="!isNew&&selected!==DEFAULT_THEME_ID" type="button" :disabled="!usageComplete||usage>0" @click="remove">Eliminar sin uso</button></div><small v-if="!usageComplete">Eliminación desactivada: no se ha podido verificar el uso en publicaciones.</small></details>
    </div>
    <aside><div class="preview-heading"><h3>Vista previa</h3><div class="segmented"><button :aria-pressed="previewMode==='social'" @click="previewMode='social'">Social</button><button :aria-pressed="previewMode==='web'" @click="previewMode='web'">Artículo</button></div></div><VisualThemePreview v-if="form" :theme="form" :mode="previewMode"/><small>Ejemplo de colores y decoración. Revisa el generador antes de exportar.</small></aside>
   </div>
  </template>
 </section>
</template>
<style scoped>
.visual-theme-manager{color:var(--text-primary,#fff);padding:20px;min-width:0}.visual-theme-manager header,.editor-heading,.preview-heading{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.visual-theme-manager h2{font-size:24px}.visual-theme-manager h3{font-size:17px;font-weight:750;margin:0}.visual-theme-manager p,.visual-theme-manager small{color:var(--text-muted,#b8bfd5);line-height:1.6}.visual-theme-manager small{font-size:11px}.visual-theme-manager button,.theme-file{border:1px solid var(--border,#ffffff26);background:var(--admin-surface,#171b31);color:inherit;padding:10px 12px;border-radius:10px;cursor:pointer;font:inherit;font-size:12px}.visual-theme-manager button:disabled{opacity:.5;cursor:not-allowed}.theme-gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px;margin:20px 0 28px}.theme-gallery button{text-align:left;display:grid;align-content:start;gap:6px;padding:8px;overflow:hidden}.theme-gallery button.selected{border-color:#c084fc;box-shadow:0 0 0 2px #c084fc33;background:#7024dc22}.theme-gallery strong{font-size:12px;padding:0 3px}.theme-gallery small{padding:0 3px}.theme-cover{height:88px;border-radius:7px;position:relative;overflow:hidden;padding:25px 15px 12px}.sample-line{display:block;width:65%;height:7px;border-radius:4px;margin-bottom:7px}.sample-line.short{width:40%;height:5px}.theme-swatches{display:flex;gap:4px;position:absolute;right:9px;bottom:8px;z-index:3}.theme-swatches i{width:13px;height:13px;border:1px solid #ffffff55;border-radius:50%}.theme-manager-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(260px,340px);gap:28px;align-items:start}.theme-manager-layout>*{min-width:0}.theme-draft{padding:22px;background:#090c1b44;border:1px solid #ffffff14;border-radius:16px}.segmented,.group-tabs{display:flex;gap:4px;flex-wrap:wrap}.segmented button{padding:6px 10px;font-size:11px}.segmented button[aria-pressed=true],.group-tabs button[aria-pressed=true]{background:#7024dc55;border-color:#c084fc}.group-tabs{margin:20px 0 16px}.theme-basics{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:20px}.theme-basics label,.theme-colors label{display:grid;gap:7px;font-size:12px}.theme-hint{font-size:11px;margin:12px 0}.theme-colors{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.visual-theme-manager input:not([type=checkbox]):not([type=range]):not([type=color]),.visual-theme-manager select{width:100%;min-width:0;background:var(--admin-bg,#090c1b);color:inherit;border:1px solid #ffffff26;padding:9px;border-radius:8px;font-size:12px}.color-control{display:flex;gap:8px;align-items:center}.color-control input[type=color]{width:38px;height:36px;flex:none;padding:2px;border:1px solid #ffffff33;border-radius:8px;background:transparent;cursor:pointer}.range-control{display:flex;gap:10px;align-items:center}.range-control input{width:100%;accent-color:#c084fc}.range-control output{min-width:35px;font-size:11px}.theme-actions,.theme-integrations{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}.theme-integrations{align-items:center;background:#ffffff05;padding:12px 16px;border-radius:10px}.theme-integrations label{display:flex;align-items:center;gap:8px;font-size:12px}.theme-integrations small{margin-left:auto}.theme-actions .save-theme{background:linear-gradient(120deg,#7c3aed,#bd2f91);border-color:transparent;color:white;font-weight:700}.theme-file input{display:none}.theme-error{color:#fda4af!important;font-size:12px}.json-editor{display:grid;gap:8px;margin-top:20px;font-size:12px}.json-editor textarea{width:100%;height:420px;resize:vertical;background:var(--admin-bg,#090c1b);color:inherit;border:1px solid #ffffff33;border-radius:12px;padding:12px;font:12px/1.6 monospace;box-sizing:border-box}.advanced-actions{border-top:1px solid #ffffff15;padding-top:14px}.advanced-actions summary{cursor:pointer;font-size:12px;color:#c4b5fd}.theme-manager-layout aside{position:sticky;top:20px;display:grid;gap:14px}.preview-heading h3{font-size:14px}.theme-manager-layout aside :deep(.theme-preview){max-width:none}@media(max-width:1000px){.theme-manager-layout{grid-template-columns:minmax(0,1fr)}.theme-manager-layout aside{position:static;max-width:400px;width:100%;grid-row:1}.theme-colors{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.visual-theme-manager{padding:8px}.theme-gallery{grid-template-columns:repeat(2,minmax(0,1fr))}.theme-basics,.theme-colors{grid-template-columns:1fr}.theme-draft{padding:14px}.theme-integrations small{margin-left:0}}
</style>
